import{_ as o}from"./chunks/analytics_spotify_discovery.CA1B06lf.js";import{_ as t}from"./chunks/analytics_episode_explorer.BWRHWryF.js";import{_ as s,c as a,b as n,a0 as i}from"./chunks/framework.DZ_FiXNr.js";const r="/images/analytics_apple_episode_detail.webp",l="/images/analytics_overview.webp",b=JSON.parse(`{"title":"Why You Should Claim Your Podcast on Apple Podcasts and Spotify","description":"Your hosting platform can put your show on Apple Podcasts and Spotify for you. Here's why you should still claim it in Apple Podcasts Connect and Spotify for Creators: real listener data, promotion tools, and one place in PodSEO to read it all next to your downloads.","frontmatter":{"description":"Your hosting platform can put your show on Apple Podcasts and Spotify for you. Here's why you should still claim it in Apple Podcasts Connect and Spotify for Creators: real listener data, promotion tools, and one place in PodSEO to read it all next to your downloads."},"headers":[],"relativePath":"academy/why-you-should-claim-your-podcast-on-apple-and-spotify.md","filePath":"academy/why-you-should-claim-your-podcast-on-apple-and-spotify.md"}`),h={name:"academy/why-you-should-claim-your-podcast-on-apple-and-spotify.md"};function p(d,e,c,u,y,m){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="why-you-should-claim-your-podcast-on-apple-podcasts-and-spotify" tabindex="-1">Why You Should Claim Your Podcast on Apple Podcasts and Spotify <a class="header-anchor" href="#why-you-should-claim-your-podcast-on-apple-podcasts-and-spotify" aria-label="Permalink to &quot;Why You Should Claim Your Podcast on Apple Podcasts and Spotify&quot;">​</a></h1><p>If your hosting platform offered to &quot;submit your show to Apple Podcasts and Spotify&quot; with one click, you probably said yes. It&#39;s convenient, and your show went live on both apps without you ever creating an account there.</p><p>There&#39;s a catch most podcasters only discover later: being <strong>listed</strong> on Apple Podcasts and Spotify is not the same as <strong>owning</strong> your show there. Until you claim it, the platform has your episodes, but you can&#39;t see what the platform knows about your listeners, and you can&#39;t use the tools it gives show owners to make the show more attractive.</p><p>This guide explains what claiming means, why your host&#39;s one-click submission is still a good start, what you gain once the show is yours, and how PodSEO puts all of it in one place.</p><h2 id="a-few-words-first" tabindex="-1">A Few Words First <a class="header-anchor" href="#a-few-words-first" aria-label="Permalink to &quot;A Few Words First&quot;">​</a></h2><p>A handful of terms come up again and again. Here they are in plain language:</p><ul><li><strong>Hosting platform (your host)</strong>: the service where you upload your episodes, such as Buzzsprout, Spreaker, Libsyn, Podigee, Captivate or RSS.com. It stores the audio files and publishes your feed.</li><li><strong>RSS feed</strong>: the address your host publishes with the list of your episodes. Apple Podcasts, Spotify and every other app read it to know when you have a new episode.</li><li><strong>Submitting</strong> a show: telling a platform &quot;here is my feed, please list it&quot;. Your host can do it for you.</li><li><strong>Claiming</strong> a show: proving to the platform that the show is yours, so it appears in <em>your</em> account in <strong>Apple Podcasts Connect</strong> (Apple&#39;s dashboard for podcasters) or <strong>Spotify for Creators</strong> (Spotify&#39;s). Claiming is free, and the show keeps being hosted exactly where it is.</li><li><strong>Downloads</strong>: counted on the server side, by whoever delivers the audio file (your host, or a tracking prefix such as OP3 or hopr.fm). They tell you a file was requested, not whether anyone listened.</li><li><strong>Plays and listeners</strong>: counted on the app side (client side), by Apple, Spotify or YouTube, from what happens inside their apps: who pressed play, for how long, and where they stopped.</li></ul><h2 id="why-letting-your-host-submit-the-show-is-a-good-start" tabindex="-1">Why Letting Your Host Submit the Show Is a Good Start <a class="header-anchor" href="#why-letting-your-host-submit-the-show-is-a-good-start" aria-label="Permalink to &quot;Why Letting Your Host Submit the Show Is a Good Start&quot;">​</a></h2><p>Hosts offer one-click submission because it removes a fiddly step, and in some cases it&#39;s the better way to get on a platform in the first place.</p><p>Spotify is the clearest example. When a show reaches Spotify through a plain feed submission, Spotify can keep its own copy of each episode and play that copy to its listeners. That has two side effects:</p><ul><li><strong>Dynamic ad insertion stops working on Spotify.</strong> Dynamic ad insertion (DAI) is when your host stitches an ad, a promo or an updated message into the episode at the moment someone plays it, instead of recording it into the file. If Spotify plays its own stored copy, there is no &quot;moment of playing&quot; at your host, so the ad your host would have inserted never reaches Spotify listeners.</li><li><strong>Your host may undercount Spotify listening</strong>, because the audio is no longer requested from your host each time.</li></ul><p>Many hosts have a direct delivery arrangement with Spotify (some call it &quot;passthrough&quot;) so that Spotify streams the file from the host instead of its own copy, and dynamic ads and download counting keep working. When your host&#39;s Spotify option uses an arrangement like this, submitting through the host is the way to go. Check your host&#39;s own documentation: each one describes what its Spotify connection does.</p><p>On Apple Podcasts, many hosts submit the show <strong>under their own Apple account</strong>. It works fine for listeners, but it means the show sits in your host&#39;s Apple Podcasts Connect, not yours.</p><p>Either way, the result is the same: your show is live, but nobody has claimed it in your name. Claiming afterwards doesn&#39;t undo any of this. Your host keeps delivering the episodes, the feed stays the same, and listeners notice nothing.</p><h2 id="what-you-gain-by-claiming" tabindex="-1">What You Gain by Claiming <a class="header-anchor" href="#what-you-gain-by-claiming" aria-label="Permalink to &quot;What You Gain by Claiming&quot;">​</a></h2><h3 id="who-your-listeners-really-are-not-just-how-many-files-were-downloaded" tabindex="-1">Who your listeners really are, not just how many files were downloaded <a class="header-anchor" href="#who-your-listeners-really-are-not-just-how-many-files-were-downloaded" aria-label="Permalink to &quot;Who your listeners really are, not just how many files were downloaded&quot;">​</a></h3><p>Your host can tell you how many times your audio was downloaded. Apple and Spotify can tell you what happened next, because they see listening inside their apps. Once the show is in your account, you can see, for example:</p><ul><li><strong>How many different people listened</strong> (listeners) and how many listened for a meaningful amount of time (Apple calls them engaged listeners).</li><li><strong>Followers</strong>: how many people follow the show and get new episodes automatically, and how that changes over time.</li><li><strong>Where people stop listening</strong> inside each episode. If half your audience leaves at minute 8, you know exactly which part to look at.</li><li><strong>Who your audience is</strong>: age range, gender, countries and cities, as reported by each platform.</li><li><strong>How people find you</strong>: on Spotify, how many times your show was shown to someone (impressions), and whether it was in search, on the Home page or in their Library, plus how many of those views turned into plays.</li></ul><p>None of this exists in a download count. A download can be an app pre-loading an episode nobody opens; a play with a listening curve is a person.</p><p><a href="/images/analytics_apple_episode_detail.webp" title="Open screenshot at full size"><img src="'+r+'" alt="Apple Podcasts episode report showing the listening curve second by second"></a></p><p><em>An Apple Podcasts episode report in PodSEO: the line shows how many people were still listening at each moment of the episode.</em></p><p><a href="/images/analytics_spotify_discovery.webp" title="Open screenshot at full size"><img src="'+o+'" alt="Spotify Discovery report showing impressions by source: Search, Home, Library"></a></p><p><em>Spotify&#39;s Discovery report: how often the show was shown, where (Search, Home, Library), and how many of those views turned into plays.</em></p><h3 id="a-show-that-looks-better-on-the-platform-itself" tabindex="-1">A show that looks better on the platform itself <a class="header-anchor" href="#a-show-that-looks-better-on-the-platform-itself" aria-label="Permalink to &quot;A show that looks better on the platform itself&quot;">​</a></h3><p>Claiming also unlocks the tools each platform reserves for show owners. They make your show more attractive where listeners actually decide what to play:</p><ul><li><strong>On Apple Podcasts</strong>: upload extra artwork, such as Full Page Show Art (a tall version of your cover shown on your show page and in the player) and the wide artwork Apple asks for when you submit your show for featuring, check your show&#39;s status, and refresh the feed when a new episode is late to appear.</li><li><strong>On Spotify</strong>: manage your show page and use the interactive and promotional features Spotify offers to show owners in your region.</li></ul><p>The details change as Apple and Spotify add features, but they have one thing in common: you can only use them on a show you&#39;ve claimed.</p><h3 id="control-over-who-can-see-your-data" tabindex="-1">Control over who can see your data <a class="header-anchor" href="#control-over-who-can-see-your-data" aria-label="Permalink to &quot;Control over who can see your data&quot;">​</a></h3><p>A claimed show has a team. You decide who joins it and with which role: a co-host, a producer, an agency, or a read-only service like PodSEO. Nobody else can see your listener data, and you can remove access at any time.</p><h2 id="how-to-claim-your-show" tabindex="-1">How to Claim Your Show <a class="header-anchor" href="#how-to-claim-your-show" aria-label="Permalink to &quot;How to Claim Your Show&quot;">​</a></h2><p>Claiming takes a few minutes per platform:</p><ul><li><strong>Spotify</strong>: sign in to Spotify for Creators, choose <strong>Add a new show</strong>, then <strong>Find an existing show</strong>, and enter your RSS feed or your Spotify show link. Spotify emails a code to the address in your RSS feed. <strong>Don&#39;t create a new show or upload your episodes again</strong>: that makes a second, separate copy of your podcast.</li><li><strong>Apple Podcasts</strong>: sign in to Apple Podcasts Connect with your own Apple Account, use <strong>Claim Existing Show</strong> and paste your show&#39;s Apple link. Apple gives you a token that you paste in your host&#39;s settings.</li></ul><p>Before you start, check that your RSS feed contains an email address you can read: it&#39;s where the platforms send their confirmation. Some hosts leave it out by default and have a setting to add it.</p><p>The full step-by-step instructions, including what to do if the show is already claimed or the code never arrives, are in <a href="/features/analytics-connections.html#can-t-find-your-podcast-in-spotify-manage">Connect Your Analytics</a> (Spotify) and <a href="/features/analytics-connections.html#can-t-find-your-show-in-apple-podcasts-connect">the Apple section of the same guide</a>.</p><h2 id="why-read-it-all-in-podseo" tabindex="-1">Why Read It All in PodSEO <a class="header-anchor" href="#why-read-it-all-in-podseo" aria-label="Permalink to &quot;Why Read It All in PodSEO&quot;">​</a></h2><p>Once your show is claimed, each platform shows you its own dashboard, and your host shows you another one. Each answers a different question, and none of them shows the others&#39; numbers. PodSEO brings them together in <strong>Analytics</strong>:</p><ul><li><strong>Server-side downloads</strong>: your host&#39;s own statistics (Spreaker, Buzzsprout, Simplecast, Captivate, Transistor, Podigee), and downloads counted by a tracking prefix such as <a href="/features/op3-analytics.html">OP3</a> or <a href="/features/hopr-fm-analytics.html">hopr.fm</a>. A prefix is a short address added in front of your episode links that counts each request before passing it on to your host. These numbers cover every app at once: Apple Podcasts, Spotify, Overcast, Pocket Casts and the rest.</li><li><strong>Client-side listening</strong>: plays, listeners, followers, audience and discovery as measured inside <a href="/features/apple-podcasts-analytics.html">Apple Podcasts</a>, <a href="/features/spotify-analytics.html">Spotify</a> and <a href="/features/youtube-insights.html">YouTube</a> (for YouTube there&#39;s nothing to claim: you connect the channel you already own).</li></ul><p>One prefix is enough: stacking several trackers on the same feed causes more problems than it solves (see <a href="/academy/why-multiple-podcast-trackers-are-a-recipe-for-disaster.html">Why Multiple Podcast Trackers Are a Recipe for Disaster</a>).</p><p>Side by side, the two halves explain each other. Downloads tell you how far your episodes travel; plays, completion and discovery tell you who actually listened and how they found you. <a href="/academy/podcast-analytics-decoded-which-metrics-actually-matter-for-seo.html">Podcast Analytics Decoded</a> goes through which of these numbers matter most for being found. In <strong>Analytics → Overview → Timeline</strong>, every connected source sits on the same calendar, next to your releases and changes to your show, each on its own scale. PodSEO never adds the numbers together, because each platform counts something different.</p><p><a href="/images/analytics_overview.webp" title="Open screenshot at full size"><img src="'+l+'" alt="Analytics Overview timeline with Spreaker downloads, Apple Podcasts plays, Spotify plays, YouTube views and hopr.fm downloads"></a></p><p><em>Analytics → Overview: host downloads, Apple Podcasts and Spotify plays, YouTube views and hopr.fm downloads on one timeline.</em></p><p>In <strong>Analytics → Overview → Across platforms</strong>, you can pick one episode and compare it across every connected source, including the listening curves from Apple and Spotify. And because it&#39;s all in the same place as your keyword rankings and show optimization, you can check whether a new title brought more Search impressions on Spotify, not just more downloads.</p><p><a href="/images/analytics_episode_explorer.webp" title="Open screenshot at full size"><img src="'+t+'" alt="Episode explorer comparing one episode across connected platforms"></a></p><h2 id="common-questions" tabindex="-1">Common Questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common Questions&quot;">​</a></h2><p><strong>Will claiming change anything for my listeners or my host?</strong> No. The show stays hosted where it is, the feed stays the same, and your episodes keep appearing as before. Claiming only adds you as the owner on the platform.</p><p><strong>I already submitted through my host. Do I need to submit again?</strong> No, and please don&#39;t. Claim the existing show instead. Submitting or uploading again creates a duplicate show that splits your listeners and your rankings.</p><p><strong>Does PodSEO get control of my show?</strong> No. On Spotify you invite PodSEO with <strong>Analytics: Reader</strong> and everything else on <strong>No access</strong>; on Apple with the <strong>Analyst</strong> role. Both are read-only: PodSEO can see numbers, never change your show.</p><p><strong>Is claiming free?</strong> Yes, on both platforms.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ol><li>Check your RSS feed has an email you can read.</li><li>Claim your show on Spotify for Creators and Apple Podcasts Connect.</li><li>In PodSEO, open <strong>Analytics</strong>, pick <strong>Spotify</strong> or <strong>Apple Podcasts</strong>, and follow the connection steps. Your host&#39;s numbers, a tracking prefix and YouTube can be connected from the same page.</li></ol><p>New to PodSEO? <a href="https://podseo.com/features/analytics/?utm_source=help&amp;utm_medium=referral&amp;utm_campaign=academy&amp;utm_content=why-you-should-claim-your-podcast-on-apple-and-spotify" target="_blank" rel="noreferrer">See what Analytics shows once your sources are connected</a>.</p>',51)])])}const S=s(h,[["render",p]]);export{b as __pageData,S as default};
